// src/config.ts
import fs from 'fs-extra';
import path from 'path';

interface ConsolidationConfig {
  sources: string[];
  targets: Record<string, string>;
  footnoting: {
    format: string;
    style: string;
  };
  preservation: {
    zeroLoss: boolean;
    sourceReferences: boolean;
  };
  dryRun?: boolean;
}

export async function loadConfig(cliOptions: any): Promise<ConsolidationConfig> {
  // Load default config
  const defaultConfig = await fs.readJSON(path.resolve(__dirname, '../config/default.json'));

  // Override with CLI options
  if (cliOptions.source) {
    defaultConfig.sources = cliOptions.source.split(',');
  }

  if (cliOptions.target) {
    // Update target directory for all doc types
    Object.keys(defaultConfig.targets).forEach(key => {
      defaultConfig.targets[key] = path.join(cliOptions.target, path.basename(defaultConfig.targets[key]));
    });
  }

  if (cliOptions.type) {
    const types = cliOptions.type.split(',');
    const filteredTargets: Record<string, string> = {};
    types.forEach(type => {
      if (defaultConfig.targets[type]) {
        filteredTargets[type] = defaultConfig.targets[type];
      }
    });
    defaultConfig.targets = filteredTargets;
  }

  defaultConfig.dryRun = !!cliOptions.dryRun;

  return defaultConfig;
}
