```typescript
// src/parsers/markdown-parser.ts
import fs from 'fs-extra';
import MarkdownIt from 'markdown-it';
import { DocumentMetadata, ParsedDocument, DocumentSection } from './types';

const md = new MarkdownIt();

export async function parseMarkdownFile(metadata: DocumentMetadata): Promise<ParsedDocument> {
  const content = await fs.readFile(metadata.path, 'utf-8');
  const sections = parseMarkdownSections(content);

  return {
    metadata,
    content,
    sections
  };
}

function parseMarkdownSections(content: string): DocumentSection[] {
  const lines = content.split('\n');
  const rootSections: DocumentSection[] = [];
  let currentSection: DocumentSection | null = null;
  let sectionContent: string[] = [];

  for (const line of lines) {
    const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);

    if (headingMatch) {
      // Save previous section if exists
      if (currentSection) {
        currentSection.content = sectionContent.join('\n');
        sectionContent = [];
      }

      // Create new section
      const level = headingMatch[1].length;
      const title = headingMatch[2].trim();

      const newSection: DocumentSection = {
        title,
        level,
        content: '',
        subsections: []
      };

      if (!currentSection || level <= currentSection.level) {
        // This is a top-level section or same level
        rootSections.push(newSection);
        currentSection = newSection;
      } else {
        // This is a subsection
        let parent = rootSections[rootSections.length - 1];
        while (parent.subsections.length > 0 && parent.subsections[parent.subsections.length - 1].level < level) {
          parent = parent.subsections[parent.subsections.length - 1];
        }
        parent.subsections.push(newSection);
        currentSection = newSection;
      }
    } else {
      // Add to current section content
      sectionContent.push(line);
    }
  }

  // Save the last section
  if (currentSection) {
    currentSection.content = sectionContent.join('\n');
  }

  return rootSections;
}
