2. Implement document categorization:
```typescript
// src/analyzers/categorizer.ts
import { ParsedDocument } from '../parsers/types';
import { AnalyzedDocument } from './types';

const CATEGORY_KEYWORDS = {
  'system-guide': ['system', 'guide', 'architecture', 'overview', 'design'],
  'troubleshooting': ['troubleshoot', 'issue', 'error', 'problem', 'debug', 'fix'],
  'setup': ['setup', 'installation', 'configure', 'install', 'getting started', 'claude']
};

export function categorizeDocument(doc: ParsedDocument): AnalyzedDocument {
  const scores: Record<string, number> = {};

  // Initialize scores
  Object.keys(CATEGORY_KEYWORDS).forEach(category => {
    scores[category] = 0;
  });

  // Score based on filename
  Object.entries(CATEGORY_KEYWORDS).forEach(([category, keywords]) => {
    keywords.forEach(keyword => {
      if (doc.metadata.filename.toLowerCase().includes(keyword.toLowerCase())) {
        scores[category] += 5;
      }
    });
  });

  // Score based on content
  Object.entries(CATEGORY_KEYWORDS).forEach(([category, keywords]) => {
    keywords.forEach(keyword => {
      const regex = new RegExp(keyword, 'gi');
      const matches = (doc.content.match(regex) || []).length;
      scores[category] += matches;
    });
  });

  // Find highest scoring category
  let bestCategory = 'uncategorized';
  let highestScore = 0;

  Object.entries(scores).forEach(([category, score]) => {
    if (score > highestScore) {
      highestScore = score;
      bestCategory = category;
    }
  });

  // Extract themes (top keywords)
  const words = doc.content.toLowerCase()
    .replace(/[^\w\s]/g, '')
    .split(/\s+/)
    .filter(word => word.length > 3);

  const wordFrequency: Record<string, number> = {};
  words.forEach(word => {
    wordFrequency[word] = (wordFrequency[word] || 0) + 1;
  });

  const themes = Object.entries(wordFrequency)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([word]) => word);

  // Calculate relevance score based on recency and content length
  const ageInDays = (Date.now() - doc.metadata.lastModified.getTime()) / (1000 * 60 * 60 * 24);
  const recencyScore = Math.max(0, 100 - ageInDays) / 100; // 0-1 score, higher for newer docs
  const contentScore = Math.min(1, doc.content.length / 5000); // 0-1 score, higher for longer docs
  const relevanceScore = (recencyScore * 0.7) + (contentScore * 0.3); // Weighted score

  return {
    ...doc,
    category: bestCategory,
    themes,
    relevanceScore,
    duplicateGroups: []
  };
}
