// src/analyzers/duplicate-detector.ts
import { AnalyzedDocument, DuplicateGroup } from './types';

export function detectDuplicates(documents: AnalyzedDocument[]): AnalyzedDocument[] {
  const contentMap = new Map<string, {
    documentPath: string;
    sectionTitle: string;
  }[]>();

  // Extract sections from all documents
  documents.forEach(doc => {
    const extractSections = (sections: any[], path: string) => {
      sections.forEach(section => {
        // Normalize content for comparison
        const normalizedContent = section.content
          .trim()
          .replace(/\s+/g, ' ')
          .toLowerCase();

        // Only consider substantial content
        if (normalizedContent.length > 50) {
          if (!contentMap.has(normalizedContent)) {
            contentMap.set(normalizedContent, []);
          }

          contentMap.get(normalizedContent)!.push({
            documentPath: path,
            sectionTitle: section.title
          });
        }

        // Process subsections
        if (section.subsections && section.subsections.length > 0) {
          extractSections(section.subsections, path);
        }
      });
    };

    extractSections(doc.sections, doc.metadata.path);
  });

  // Find duplicates
  const duplicateGroups: DuplicateGroup[] = [];

  contentMap.forEach((locations, content) => {
    if (locations.length > 1) {
      duplicateGroups.push({
        content,
        locations
      });
    }
  });

  // Assign duplicate groups to documents
  return documents.map(doc => {
    const docDuplicates = duplicateGroups.filter(group => 
      group.locations.some(loc => loc.documentPath === doc.metadata.path)
    );

    return {
      ...doc,
      duplicateGroups: docDuplicates
    };
  });
}
