import { ParsedDocument } from '../parsers/types';
import { AnalyzedDocument, DocumentCategory } from './types';
import { categorizeDocument } from './categorizer';
import { detectDuplicates } from './duplicate-detector';

export async function analyzeDocuments(documents: ParsedDocument[]): Promise<DocumentCategory[]> {
  // Step 1: Categorize each document
  let analyzedDocs = documents.map(categorizeDocument);

  // Step 2: Detect duplicates across all documents
  analyzedDocs = detectDuplicates(analyzedDocs);

  // Step 3: Group by category
  const categories: Record<string, AnalyzedDocument[]> = {};

  analyzedDocs.forEach(doc => {
    if (!categories[doc.category]) {
      categories[doc.category] = [];
    }
    categories[doc.category].push(doc);
  });

  // Step 4: Sort documents within each category by relevance
  return Object.entries(categories).map(([name, docs]) => ({
    name,
    documents: docs.sort((a, b) => b.relevanceScore - a.relevanceScore)
  }));
}

export { AnalyzedDocument, DocumentCategory } from './types';
