```typescript
// src/generators/footnoting/generator.ts
import path from 'path';
import { FootnoteReference, FootnotedContent } from './types';
import { AnalyzedDocument } from '../../analyzers/types';

export function generateFootnotes(content: string, sourceDoc: AnalyzedDocument): FootnotedContent {
  const footnotes: FootnoteReference[] = [];
  let footnoteId = 1;
  let footnoteContent = content;

  // Extract sections that need footnotes
  sourceDoc.sections.forEach(section => {
    const processSection = (sect: any, depth = 0) => {
      // Skip very small sections
      if (sect.content.length < 30) return;

      const footnote: FootnoteReference = {
        id: footnoteId++,
        sourcePath: sourceDoc.metadata.path,
        sourceTitle: sourceDoc.metadata.filename,
        content: sect.title,
        context: sect.content.substring(0, 100) + (sect.content.length > 100 ? '...' : '')
      };

      footnotes.push(footnote);

      // Process subsections
      if (sect.subsections && sect.subsections.length > 0) {
        sect.subsections.forEach((subsect: any) => processSection(subsect, depth + 1));
      }
    };

    processSection(section);
  });

  return {
    content: footnoteContent,
    footnotes
  };
}

export function applyFootnotesToContent(content: string, footnotes: FootnoteReference[]): string {
  let result = content;

  // Apply footnotes to content
  footnotes.forEach(footnote => {
    // Look for the section title in the content
    const regex = new RegExp(`(${footnote.content.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'g');
    result = result.replace(regex, `$1 [${footnote.id}]`);
  });

  // Add footnotes section at the end
  result += '\n\n## References\n\n';
  footnotes.forEach(footnote => {
    const relativePath = path.basename(footnote.sourcePath);
    result += `[${footnote.id}]: ${relativePath} - ${footnote.content}\n`;
  });

  return result;
}

export function mergeFootnotes(existingFootnotes: FootnoteReference[], newFootnotes: FootnoteReference[]): FootnoteReference[] {
  // Start new footnote IDs after the highest existing ID
  const highestId = existingFootnotes.length > 0 
    ? Math.max(...existingFootnotes.map(f => f.id))
    : 0;

  const updatedNewFootnotes = newFootnotes.map((footnote, index) => ({
    ...footnote,
    id: highestId + index + 1
  }));

  return [...existingFootnotes, ...updatedNewFootnotes];
}
