// src/generators/footnoting/extractor.ts
import { FootnoteReference } from './types';

export function extractExistingFootnotes(content: string): FootnoteReference[] {
  const footnotes: FootnoteReference[] = [];

  // Look for reference section
  const referenceSection = content.match(/## References\s+([\s\S]+)$/i);

  if (!referenceSection) return [];

  // Extract footnote definitions
  const footnoteRegex = /\[(\d+)\]:\s+(.+?)\s+-\s+(.+?)$/gm;
  let match;

  while ((match = footnoteRegex.exec(referenceSection[1])) !== null) {
    const id = parseInt(match[1], 10);
    const sourcePath = match[2].trim();
    const content = match[3].trim();

    footnotes.push({
      id,
      sourcePath,
      sourceTitle: sourcePath, // We don't have the original title
      content
    });
  }

  return footnotes.sort((a, b) => a.id - b.id);
}
