{{references}}
`
};

// Default template for any category
const DEFAULT_TEMPLATE = `# {{title}}

## Overview
{{overview}}

## Content
{{content}}

## References
{{references}}
`;

export function getTemplateForCategory(category: string): string {
  return TEMPLATES[category] || DEFAULT_TEMPLATE.replace('{{title}}', category.charAt(0).toUpperCase() + category.slice(1));
}

export function fillTemplate(template: string, category: DocumentCategory): string {
  let result = template;

  // Extract all placeholders
  const placeholders = template.match(/\{\{([^}]+)\}\}/g) || [];

  placeholders.forEach(placeholder => {
    const key = placeholder.replace(/[{}]/g, '');
    let content = '';

    // Skip references placeholder - will be filled later
    if (key === 'references') return;

    // For each placeholder, find relevant content from documents
    category.documents.forEach(doc => {
      doc.sections.forEach(section => {
        const processSection = (sect: any, depth = 0) => {
          // Check if section title matches placeholder
          if (sect.title.toLowerCase().includes(key.toLowerCase())) {
            content += `${sect.content}\n\n`;
          }

          // Process subsections
          if (sect.subsections && sect.subsections.length > 0) {
            sect.subsections.forEach((subsect: any) => processSection(subsect, depth + 1));
          }
        };

        processSection(section);
      });
    });

    // If no specific content found, use general content from top documents
    if (!content && key !== 'title' && key !== 'overview') {
      const topDocs = category.documents.slice(0, 3); // Use top 3 docs
      topDocs.forEach(doc => {
        if (doc.sections.length > 0) {
          content += `### From ${doc.metadata.filename}\n\n`;
          content += doc.sections[0].content + '\n\n';
        }
      });
    }

    // For overview, use document themes and first paragraphs
    if (key === 'overview' && !content) {
      content = `This document consolidates information about ${category.name} from multiple sources.\n\n`;
      content += `Key topics include: ${category.documents.flatMap(d => d.themes).slice(0, 5).join(', ')}.\n\n`;

      // Add first paragraph from top document
      if (category.documents.length > 0 && category.documents[0].sections.length > 0) {
        const firstPara = category.documents[0].sections[0].content.split('\n\n')[0];
        if (firstPara) content += firstPara + '\n\n';
      }
    }

    result = result.replace(placeholder, content.trim());
  });

  return result;
}
