// src/generators/content/generator.ts
import fs from 'fs-extra';
import path from 'path';
import { DocumentCategory } from '../../analyzers/types';
import { GenerationConfig, GeneratedDocument } from './types';
import { getTemplateForCategory, fillTemplate } from './templates';
import { 
  generateFootnotes, 
  applyFootnotesToContent, 
  extractExistingFootnotes, 
  mergeFootnotes,
  FootnoteReference 
} from '../footnoting';

export async function generateDocument(category: DocumentCategory, config: GenerationConfig): Promise<GeneratedDocument> {
  // Step 1: Get template for this category
  const template = getTemplateForCategory(config.category);

  // Step 2: Fill template with content
  let content = fillTemplate(template, category);

  // Step 3: Generate footnotes for all documents in category
  const allFootnotes: FootnoteReference[] = [];

  category.documents.forEach(doc => {
    const { footnotes } = generateFootnotes(content, doc);
    allFootnotes.push(...footnotes);
  });

  // Step 4: Check if target file exists and has footnotes
  let existingFootnotes: FootnoteReference[] = [];

  if (config.preserveExisting && await fs.pathExists(config.targetFile)) {
    const existingContent = await fs.readFile(config.targetFile, 'utf-8');
    existingFootnotes = extractExistingFootnotes(existingContent);

    // Preserve existing content structure but update with new information
    if (existingContent.length > 0) {
      // Simple merge strategy - keep existing content but add new sections
      const existingSections = existingContent.split('\n## ');
      const newSections = content.split('\n## ');

      // Combine sections, preferring existing ones but adding new ones
      const combinedSections = [...existingSections];

      newSections.forEach(newSection => {
        const sectionTitle = newSection.split('\n')[0];
        const existingSectionIndex = existingSections.findIndex(s => 
          s.split('\n')[0].toLowerCase() === sectionTitle.toLowerCase()
        );

        if (existingSectionIndex === -1) {
          // This is a new section, add it
          combinedSections.push(newSection);
        }
      });

      // Rebuild content, ensuring first section doesn't get '## ' prefix
      content = combinedSections[0] + combinedSections.slice(1).map(s => `\n## ${s}`).join('');
    }
  }

  // Step 5: Merge footnotes and apply to content
  const mergedFootnotes = mergeFootnotes(existingFootnotes, allFootnotes);
  const finalContent = applyFootnotesToContent(content, mergedFootnotes);

  return {
    path: config.targetFile,
    content: finalContent,
    footnotes: mergedFootnotes
  };
}
