// src/consolidation.ts
import fs from 'fs-extra';
import path from 'path';
import { parseDocuments } from './parsers';
import { analyzeDocuments } from './analyzers';
import { generateDocument, GenerationConfig } from './generators/content';

interface ConsolidationConfig {
  sources: string[];
  targets: Record<string, string>;
  footnoting: {
    format: string;
    style: string;
  };
  preservation: {
    zeroLoss: boolean;
    sourceReferences: boolean;
  };
  dryRun?: boolean;
}

export async function consolidate(config: ConsolidationConfig): Promise<void> {
  console.log('Starting documentation consolidation...');
  console.log(`Source directories: ${config.sources.join(', ')}`);
  console.log(`Target files: ${Object.values(config.targets).join(', ')}`);

  if (config.dryRun) {
    console.log('DRY RUN MODE - No files will be modified');
  }

  // Step 1: Parse all documents from source directories
  console.log('Parsing documents...');
  const parsedDocuments = await parseDocuments(config.sources);
  console.log(`Found ${parsedDocuments.length} documents`);

  // Step 2: Analyze documents and categorize them
  console.log('Analyzing and categorizing documents...');
  const documentCategories = await analyzeDocuments(parsedDocuments);
  console.log(`Identified ${documentCategories.length} document categories`);

  // Step 3: Generate consolidated documents for each target
  console.log('Generating consolidated documents...');
  const generatedDocuments = [];

  for (const [category, targetFile] of Object.entries(config.targets)) {
    // Find matching category from analysis
    const matchingCategory = documentCategories.find(c => c.name === category);

    if (!matchingCategory) {
      console.log(`No documents found for category: ${category}`);
      continue;
    }

    console.log(`Generating ${targetFile} from ${matchingCategory.documents.length} documents`);

    const generationConfig: GenerationConfig = {
      category,
      targetFile,
      preserveExisting: config.preservation.zeroLoss,
      footnoteStyle: config.footnoting.style
    };

    const generatedDoc = await generateDocument(matchingCategory, generationConfig);
    generatedDocuments.push(generatedDoc);

    // Write file if not in dry run mode
    if (!config.dryRun) {
      // Ensure target directory exists
