    console.log(`Would process ${parsedDocuments.length} documents`);
    console.log(`Would generate ${generatedDocuments.length} consolidated files`);
    console.log(`Total footnotes: ${generatedDocuments.reduce((sum, doc) => sum + doc.footnotes.length, 0)}`);
