4. Create a utility for detecting out-of-sync documentation:
```typescript
// src/utils/sync-detector.ts
import fs from 'fs-extra';
import path from 'path';

export async function detectOutOfSync(sources: string[], targets: Record<string, string>): Promise<boolean> {
  let isOutOfSync = false;

  // Check if any source files are newer than target files
  for (const sourceDir of sources) {
    if (!await fs.pathExists(sourceDir)) continue;

    const sourceFiles = await fs.readdir(sourceDir);

    for (const sourceFile of sourceFiles) {
      const sourcePath = path.join(sourceDir, sourceFile);
      const sourceStat = await fs.stat(sourcePath);

      // Skip directories
      if (sourceStat.isDirectory()) continue;

      // Check against each target file
      for (const targetFile of Object.values(targets)) {
        if (!await fs.pathExists(targetFile)) {
          isOutOfSync = true;
          console.log(`Target file ${targetFile} does not exist - consolidation needed`);
          continue;
        }

        const targetStat = await fs.stat(targetFile);

        if (sourceStat.mtime > targetStat.mtime) {
          isOutOfSync = true;
          console.log(`Source file ${sourcePath} is newer than target ${targetFile} - consolidation needed`);
        }
      }
    }
  }

  return isOutOfSync;
}
```

